<?php
namespace App\Domain\AI\Knowledge\Services;use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Knowledge\Data\KnowledgeContentData;use App\Domain\AI\Knowledge\Enums\{KnowledgeSourceStatus,KnowledgeVersionStatus};use App\Domain\AI\Knowledge\Exceptions\{ArchivedKnowledgeSourceException,KnowledgeApprovalConflictException};use App\Domain\AI\Knowledge\Models\{KnowledgeSource,KnowledgeSourceVersion};use App\Domain\AI\Support\CanonicalJsonHasher;use App\Models\User;use Illuminate\Support\Facades\DB;
final class ApproveKnowledgeVersionService{public function __construct(private AiLifecycleAuthorization$auth,private CanonicalJsonHasher$hasher){}public function approve(User$actor,KnowledgeSourceVersion$version):KnowledgeSourceVersion{return DB::transaction(function()use($actor,$version){$a=$this->auth->authorize($actor);$source=KnowledgeSource::query()->lockForUpdate()->findOrFail($version->knowledge_source_id);if($source->status!==KnowledgeSourceStatus::Active)throw new ArchivedKnowledgeSourceException('Archived knowledge cannot be approved.');$versions=KnowledgeSourceVersion::query()->where('knowledge_source_id',$source->id)->orderBy('id')->lockForUpdate()->get();$v=$versions->firstWhere('id',$version->id)??throw new \Illuminate\Database\Eloquent\ModelNotFoundException();if($v->status!==KnowledgeVersionStatus::Draft)throw new \DomainException('Only a draft knowledge version can be approved.');$approved=$versions->where('status',KnowledgeVersionStatus::Approved);if($approved->count()>1)throw new KnowledgeApprovalConflictException('Knowledge approval state is inconsistent.');$validated=KnowledgeContentData::fromPersisted($v->content);if($validated->type!==$source->type||!hash_equals($v->checksum,$this->hasher->hash($validated->content)))throw new \DomainException('Knowledge checksum or structure is invalid.');if($previous=$approved->first())$previous->supersede($a);$v->approve($a);return$v->fresh();});}}
